class LineCounter {
public:
    explicit LineCounter(const char* path) : file_(std::fopen(path, "r")) {
        if (!file_) throw std::runtime_error("cannot open file");
    }
    ~LineCounter() { if (file_) std::fclose(file_); }
    LineCounter(const LineCounter&) = delete;
    LineCounter& operator=(const LineCounter&) = delete;

    std::size_t count() {
        std::size_t lines = 0;
        int ch;
        while ((ch = std::fgetc(file_)) != EOF) {
            if (ch == '\n') ++lines;
        }
        return lines;
    }
private:
    std::FILE* file_{};
};

int main() {
    LineCounter counter("input.txt");
    std::printf("lines=%zu\n", counter.count());
}

