namespace fs = std::filesystem;

std::string lower(std::string s) {
    for (char& c : s) c = static_cast<char>(std::tolower(static_cast<unsigned char>(c)));
    return s;
}

int main(int argc, char** argv) {
    if (argc != 2) return 2;
    std::error_code ec;
    fs::recursive_directory_iterator it(argv[1], fs::directory_options::skip_permission_denied, ec), end;
    std::unordered_map<std::string, std::size_t> counts;
    for (; it != end; it.increment(ec)) {
        if (ec) { ec.clear(); continue; }
        if (it->is_regular_file(ec) && !ec) {
            ++counts[lower(it->path().extension().string())];
        }
        ec.clear();
    }
    std::vector<std::pair<std::string, std::size_t>> rows(counts.begin(), counts.end());
    std::sort(rows.begin(), rows.end());
    for (const auto& [ext, count] : rows) std::cout << (ext.empty() ? "<none>" : ext) << " " << count << '\n';
}

