#include <algorithm>
#include <chrono>
#include <iostream>
#include <map>
#include <random>
#include <string>
#include <unordered_map>
#include <vector>

template <class F>
long long time_us(F&& f) {
    auto s = std::chrono::steady_clock::now();
    f();
    auto e = std::chrono::steady_clock::now();
    return std::chrono::duration_cast<std::chrono::microseconds>(e - s).count();
}

int main() {
    std::mt19937 rng(42);
    std::uniform_int_distribution<int> dist(0, 100000);
    std::vector<int> data(200000);
    for (int& x : data) x = dist(rng);

    std::vector<long long> map_times, hash_times;
    for (int run = 0; run < 9; ++run) {
        map_times.push_back(time_us([&]{ std::map<int,int> m; for (int x : data) ++m[x]; }));
        hash_times.push_back(time_us([&]{ std::unordered_map<int,int> m; for (int x : data) ++m[x]; }));
    }
    std::sort(map_times.begin(), map_times.end());
    std::sort(hash_times.begin(), hash_times.end());
    std::cout << "map_median_us=" << map_times[4] << "\n";
    std::cout << "unordered_map_median_us=" << hash_times[4] << "\n";
}

