struct AddCommand { int id; int priority; std::string message; };

std::optional<AddCommand> parse_add(const std::string& line) {
    std::istringstream in(line);
    std::string op;
    AddCommand cmd{};
    if (!(in >> op) || op != "ADD") return std::nullopt;
    if (!(in >> cmd.id >> cmd.priority)) return std::nullopt;
    if (cmd.priority < 0 || cmd.priority > 5) return std::nullopt;
    std::getline(in, cmd.message);
    if (!cmd.message.empty() && cmd.message.front() == ' ') cmd.message.erase(0, 1);
    if (cmd.message.empty()) return std::nullopt;
    return cmd;
}

int main() {
    std::string line;
    while (std::getline(std::cin, line)) {
        if (auto cmd = parse_add(line)) {
            std::cout << cmd->id << ' ' << cmd->priority << ' ' << cmd->message << '\n';
        } else {
            std::cout << "invalid\n";
        }
    }
}

