#include "log_parser.hpp"
#include <cctype>
#include <sstream>
#include <string>

namespace {
std::string trim_leading(std::string value) {
    std::size_t i = 0;
    while (i < value.size() && std::isspace(static_cast<unsigned char>(value[i]))) ++i;
    return value.substr(i);
}

bool valid_severity(const std::string& value) {
    return value == "DEBUG" || value == "INFO" || value == "WARN" || value == "ERROR";
}

bool valid_date_prefix(const std::string& value) {
    // This intentionally validates the YYYY-MM-DD shape, not calendar validity.
    if (value.size() != 10 || value[4] != '-' || value[7] != '-') return false;
    for (std::size_t i = 0; i < value.size(); ++i) {
        if (i == 4 || i == 7) continue;
        if (!std::isdigit(static_cast<unsigned char>(value[i]))) return false;
    }
    return true;
}
}

std::optional<LogRecord> parse_log_line(std::string_view line) {
    std::istringstream in{std::string(line)};
    LogRecord record;
    if (!(in >> record.severity >> record.timestamp)) return std::nullopt;
    if (!valid_severity(record.severity) || !valid_date_prefix(record.timestamp)) return std::nullopt;
    std::getline(in, record.message);
    record.message = trim_leading(record.message);
    if (record.message.empty() || record.message.size() > 4096) return std::nullopt;
    return record;
}

