#include "log_parser.hpp"
#include <algorithm>
#include <filesystem>
#include <fstream>
#include <future>
#include <iostream>
#include <map>
#include <stdexcept>
#include <string>
#include <vector>

struct FileReport {
    std::size_t total{0};
    std::map<std::string, std::size_t> by_severity;
    std::size_t malformed{0};
};

FileReport analyze_file(const std::string& path) {
    std::ifstream in(path);
    if (!in) throw std::runtime_error("cannot open: " + path);

    FileReport report;
    std::string line;
    while (std::getline(in, line)) {
        ++report.total;
        if (auto parsed = parse_log_line(line)) {
            ++report.by_severity[parsed->severity];
        } else {
            ++report.malformed;
        }
    }
    return report;
}

FileReport merge_reports(const std::vector<FileReport>& reports) {
    FileReport merged;
    for (const auto& report : reports) {
        merged.total += report.total;
        merged.malformed += report.malformed;
        for (const auto& [severity, count] : report.by_severity) {
            merged.by_severity[severity] += count;
        }
    }
    return merged;
}

int main(int argc, char** argv) {
    if (argc < 2) {
        std::cerr << "usage: log_analyzer <file> [file ...]\n";
        return 2;
    }

    std::vector<std::future<FileReport>> futures;
    futures.reserve(static_cast<std::size_t>(argc - 1));
    for (int i = 1; i < argc; ++i) {
        futures.push_back(std::async(std::launch::async, analyze_file, std::string(argv[i])));
    }

    std::vector<FileReport> reports;
    reports.reserve(futures.size());
    int failures = 0;
    for (std::size_t i = 0; i < futures.size(); ++i) {
        try {
            reports.push_back(futures[i].get());
        } catch (const std::exception& ex) {
            ++failures;
            std::cerr << "error: " << ex.what() << '\n';
        }
    }

    const FileReport merged = merge_reports(reports);
    std::cout << "files_processed=" << reports.size() << '\n';
    std::cout << "files_failed=" << failures << '\n';
    std::cout << "lines_seen=" << merged.total << '\n';
    std::cout << "malformed_lines=" << merged.malformed << '\n';
    for (const auto& [severity, count] : merged.by_severity) {
        std::cout << severity << '=' << count << '\n';
    }
    return failures == 0 ? 0 : 1;
}

